33	      align: "right",
34	      sortable: true,
35	      sortValue: (r) => r.amountCents,
36	      render: (r) => formatCents(r.amountCents),
37	    },
38	    {
39	      key: "actions",
40	      header: t("account.colActions"),
41	      render: (r) => (
42	        <span className="flex flex-wrap gap-3">
43	          {!r.hasReview ? (
44	            <Link
45	              href={`/session/${r.bookingId}/summary`}
46	              className="font-bold text-primary underline underline-offset-[3px]"
47	            >
48	              {t("account.leaveReview")}
49	            </Link>
50	          ) : null}
51	          <a
52	            href={`/account/receipt/${r.bookingId}`}
53	            className="font-bold text-primary underline underline-offset-[3px]"
54	          >
55	            {t("account.seeReceipt")}
56	          </a>
57	        </span>
58	      ),
59	    },
60	  ];
61	
62	  return (
63	    <DataTable
64	      caption={t("account.pastCaption")}
65	      columns={columns}
66	      rows={rows}
67	      getRowKey={(r) => r.id}
68	      emptyText={t("account.pastNone")}
69	    />
70	  );
71	}
